using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.Rendering;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class CityBridgeAccentBuild{
static CityBridgeAccentBuild(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists("CityBridgeAccent.request"))return;File.Delete("CityBridgeAccent.request");try{Build();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/BridgeAccents.txt",e.ToString());Debug.LogException(e);}}
class Buffer{public List<Vector3> p=new List<Vector3>();public List<Vector2> uv=new List<Vector2>();public List<int> ix=new List<int>();public void Strip(Vector3 a,Vector3 b,Vector3 across,float width,int color){if((b-a).sqrMagnitude<.01f)return;var s=across.normalized*width*.5f;int n=p.Count;p.AddRange(new[]{a-s,a+s,b+s,b-s});uv.AddRange(Enumerable.Repeat(new Vector2(64.25f+color,0),4));ix.AddRange(new[]{n,n+1,n+2,n,n+2,n+3});}}
static string Dir="Assets/Scenes/Oasis/BridgeLighting/LED Meshes";
static Mesh Save(Buffer b,string name){var m=new Mesh{name=name,indexFormat=b.p.Count>65535?IndexFormat.UInt32:IndexFormat.UInt16};m.SetVertices(b.p);m.SetUVs(0,b.uv);m.SetTriangles(b.ix,0);m.RecalculateNormals();m.RecalculateBounds();string path=Dir+"/"+name+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){EditorUtility.CopySerialized(m,old);UnityEngine.Object.DestroyImmediate(m);EditorUtility.SetDirty(old);return old;}AssetDatabase.CreateAsset(m,path);return m;}
static MeshRenderer Add(MeshFilter f,Buffer b,Material material){var old=f.transform.Find("Mobile bridge LED strips");if(old)UnityEngine.Object.DestroyImmediate(old.gameObject);var go=new GameObject("Mobile bridge LED strips");go.transform.SetParent(f.transform,false);go.AddComponent<MeshFilter>().sharedMesh=Save(b,f.sharedMesh.name.Replace("/","_")+" LEDs");var r=go.AddComponent<MeshRenderer>();r.sharedMaterial=material;r.shadowCastingMode=ShadowCastingMode.Off;r.receiveShadows=false;r.lightProbeUsage=LightProbeUsage.Off;r.reflectionProbeUsage=ReflectionProbeUsage.Off;r.motionVectorGenerationMode=MotionVectorGenerationMode.ForceNoMotion;GameObjectUtility.SetStaticEditorFlags(go,StaticEditorFlags.OccludeeStatic);return r;}
static void Build(){var sc=SceneManager.GetActiveScene();Directory.CreateDirectory(Dir);Directory.CreateDirectory("FinalEnvironmentRoadBackup/BeforeBridgeLEDs");if(!File.Exists("FinalEnvironmentRoadBackup/BeforeBridgeLEDs/Scene.unity"))EditorSceneManager.SaveScene(sc,"FinalEnvironmentRoadBackup/BeforeBridgeLEDs/Scene.unity",true);var material=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/BridgeLighting/Bridge Night.mat");AssetDatabase.ImportAsset(AssetDatabase.GetAssetPath(material.shader),ImportAssetOptions.ForceUpdate);if(ShaderUtil.ShaderHasError(material.shader))throw new Exception("Bridge shader compilation failed");int lights=sc.GetRootGameObjects().Sum(g=>g.GetComponentsInChildren<Light>(true).Length);var filters=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Where(f=>f.sharedMesh&&AssetDatabase.GetAssetPath(f.sharedMesh).Contains("/BridgeStructures/")&&f.sharedMesh.name.Contains("Metal")).ToArray();var added=new Dictionary<Renderer,Renderer>();int total=0;var log=new System.Text.StringBuilder();foreach(var f in filters){var mesh=f.sharedMesh;var v=mesh.vertices;var uv=mesh.uv;var b=new Buffer();var tris=mesh.triangles;for(int ti=0;ti+5<tris.Length;ti+=3){int k=tris[ti];if(k+3>=v.Length||k+3>=uv.Length)continue;if(tris[ti+1]!=k+1||tris[ti+2]!=k+2||tris[ti+3]!=k||tris[ti+4]!=k+2||tris[ti+5]!=k+3)continue;ti+=3;float width=Vector3.Distance(v[k],v[k+1]),len=Vector3.Distance(v[k+1],v[k+2]);if(len<1||len<width*1.8f||width>.0f&&width>2f)continue;int face=Mathf.RoundToInt(uv[k].x);bool cable=width<.3f;if(!cable&&face!=1&&face!=3)continue;if(cable&&k%2!=0)continue;if(cable&&!mesh.name.Contains("Bridge_1_")){var delta=f.transform.TransformVector((v[k+2]+v[k+3]-v[k]-v[k+1])*.5f);if(new Vector2(delta.x,delta.z).magnitude>Mathf.Abs(delta.y)*.12f)continue;}var across=(v[k+1]-v[k]).normalized;var normal=Vector3.Cross(v[k+1]-v[k],v[k+2]-v[k]).normalized;Vector3 a=(v[k]+v[k+1])*.5f+normal*.12f,bb=(v[k+2]+v[k+3])*.5f+normal*.12f;if(cable)b.Strip(a,bb,across,.065f,2);else{b.Strip(a-across*width*.28f,bb-across*width*.28f,across,.22f,0);b.Strip(a+across*width*.28f,bb+across*width*.28f,across,.22f,1);}}if(b.ix.Count==0)continue;var r=Add(f,b,material);added[f.GetComponent<Renderer>()]=r;total+=b.ix.Count/3;log.AppendLine(f.name+" "+f.sharedMesh.name+" strips="+b.p.Count/4+" triangles="+b.ix.Count/3);}
// Original imported bridge: follow only sharp structural edges above the deck.
var original=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).FirstOrDefault(f=>f.name=="bridge");if(original){var method=typeof(FinalPathwayRepair).GetMethod("Read",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Static);var data=method.Invoke(null,new object[]{original.sharedMesh});var type=data.GetType();var v=(Vector3[])type.GetField("p").GetValue(data);var ix=(int[])type.GetField("ids").GetValue(data);var edges=new Dictionary<string,Tuple<Vector3,Vector3,List<Vector3>>>();Func<Vector3,string> key=p=>Mathf.Round(p.x*100)+","+Mathf.Round(p.y*100)+","+Mathf.Round(p.z*100);for(int k=0;k<ix.Length;k+=3){var n=Vector3.Cross(v[ix[k+1]]-v[ix[k]],v[ix[k+2]]-v[ix[k]]).normalized;for(int j=0;j<3;j++){var a=v[ix[k+j]];var bb=v[ix[k+(j+1)%3]];string ka=key(a),kb=key(bb),id=string.CompareOrdinal(ka,kb)<0?ka+"|"+kb:kb+"|"+ka;if(!edges.ContainsKey(id))edges[id]=Tuple.Create(a,bb,new List<Vector3>());edges[id].Item3.Add(n);}}var b=new Buffer();var bounds=original.GetComponent<Renderer>().bounds;float deck=bounds.min.y+bounds.size.y*.46f;foreach(var e in edges.Values){var a=original.transform.TransformPoint(e.Item1);var bb=original.transform.TransformPoint(e.Item2);float len=Vector3.Distance(a,bb);if(Mathf.Min(a.y,bb.y)<deck||len<1||len>90||e.Item3.Count<2||!e.Item3.Any(n=>Vector3.Dot(n,e.Item3[0])<.65f))continue;var normal=e.Item3.Aggregate(Vector3.zero,(sum,n)=>sum+n).normalized;var d=e.Item2-e.Item1;var side=Vector3.Cross(d.normalized,normal);if(side.sqrMagnitude<.01f)side=Vector3.up;int color=a.x<bounds.center.x?0:1;b.Strip(e.Item1+normal*.015f,e.Item2+normal*.015f,side,.14f/Mathf.Max(.001f,original.transform.lossyScale.x),color);}if(b.p.Count>0){var rr=Add(original,b,material);var lg=rr.gameObject.AddComponent<LODGroup>();lg.SetLODs(new[]{new LOD(.018f,new Renderer[]{rr})});lg.RecalculateBounds();total+=b.ix.Count/3;log.AppendLine("Original bridge strips="+b.p.Count/4);}}
foreach(var lod in sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<LODGroup>(true))){var levels=lod.GetLODs();bool changed=false;for(int i=0;i<levels.Length;i++){var extra=levels[i].renderers.Where(r=>r&&added.ContainsKey(r)).Select(r=>added[r]).ToArray();if(extra.Length==0)continue;levels[i].renderers=levels[i].renderers.Where(r=>r&&r.name!="Mobile bridge LED strips").Concat(extra).ToArray();changed=true;}if(changed){lod.SetLODs(levels);EditorUtility.SetDirty(lod);}}
material.SetShaderPassEnabled("GBuffer",false);material.enableInstancing=true;EditorUtility.SetDirty(material);AssetDatabase.SaveAssets();if(ShaderUtil.ShaderHasError(material.shader)||lights!=sc.GetRootGameObjects().Sum(g=>g.GetComponentsInChildren<Light>(true).Length))throw new Exception("Bridge validation failed");EditorSceneManager.MarkSceneDirty(sc);EditorSceneManager.SaveScene(sc);var c=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).First();bool night=c.IsNight;try{c.Apply(true);log.AppendLine("Night="+Shader.GetGlobalFloat("_GangstarNight")+" pipeline="+GraphicsSettings.currentRenderPipeline+" material shader="+material.shader.name+" pass="+material.FindPass("MobileLED"));foreach(var rr in added.Values)log.AppendLine("LED="+rr.name+" enabled="+rr.enabled+" active="+rr.gameObject.activeInHierarchy+" bounds="+rr.bounds);var cap=typeof(CityTaxiStandBuild).GetMethod("Capture",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Static);var chosen=filters.First(f=>f.sharedMesh.name.Contains("Bridge_3_Metal_LOD0"));var bound=chosen.GetComponent<Renderer>().bounds;cap.Invoke(null,new object[]{sc,bound.center+new Vector3(45,9,85),bound.center,"Bridge-LED-Night"});c.Apply(false);cap.Invoke(null,new object[]{sc,bound.center+new Vector3(45,9,85),bound.center,"Bridge-LED-Day"});}finally{c.Apply(night);}File.WriteAllText("FinalEnvironmentRoadReview/BridgeAccents.txt","SUCCESS. Existing structures, materials and textures retained. Added thin blue/amber arch strips and cool cable accents, same existing Bridge Night material, no real-time lights, no textures sampled by LED fragment path, LOD-linked generated bridges, source meshes/colliders unchanged. Shader errors=0. Added triangles including all LOD levels="+total+"; scene lights unchanged="+lights+". Android timing unmeasured.\n"+log);}
}





